<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { can } from '../../permissions.js'
import { createClientId } from '../../clientId.js'
import { UiMessage } from '../../ui/feedback.js'
import { dutyAll } from '../../duty/api.js'
import { responseRead, responseWrite } from '../../response/api.js'
import { actionLabels, compatibleDutyRuns, correctiveActions, evidencePayload, responseTime, stateLabel, verificationPayload } from '../../response/helpers.js'
import ResponseEvidenceEditor from './ResponseEvidenceEditor.vue'
import ResponseEvidenceList from './ResponseEvidenceList.vue'
const props=defineProps({items:{type:Array,default:()=>[]},devices:{type:Array,default:()=>[]},executions:{type:Array,default:()=>[]},deviceId:String,initialId:String})
const emit=defineEmits(['refresh','navigate'])
const status=ref(''),page=ref(1),dialog=ref(false),selected=ref(null),loading=ref(false),error=ref(''),links=ref([]),linksError=ref(''),staff=ref([]),dutyRuns=ref([]),executionId=ref('')
const actionDialog=ref(false),action=ref(''),saving=ref(false),saveError=ref('')
const form=reactive({owner:'',dueAt:null,explanation:'',evidence:[],followUpExecutionId:'',result:'',items:[],runId:'',ownerId:'',nextAction:'',idempotencyKey:''})
let generation=0,detailGeneration=0,disposed=false
const rows=computed(()=>props.items.filter(row=>(!props.deviceId||row.deviceIds.includes(props.deviceId))&&(!status.value||row.body.status===status.value))),slice=computed(()=>rows.value.slice((page.value-1)*20,page.value*20))
const actionBody=computed(()=>selected.value?.body||{}),selectedDevices=computed(()=>props.devices.filter(row=>selected.value?.deviceIds.includes(row.id))),availableFollowUps=computed(()=>props.executions.filter(row=>selected.value?.deviceIds.every(id=>row.deviceIds.includes(id)))),selectedDutyRun=computed(()=>dutyRuns.value.find(row=>row.id===form.runId))
const deviceName=id=>props.devices.find(row=>row.id===id)?.name||id
const personName=id=>staff.value.find(row=>row.username===id)?.displayName||id
async function readLinks(){const token=detailGeneration,id=selected.value?.resourceId;links.value=[];linksError.value='';if(!id||!can('menu:duty'))return;try{const result=await responseRead('corrective-actions',id,'duty-links');if(token===detailGeneration&&!disposed)links.value=result.items||[]}catch(cause){if(token===detailGeneration&&!disposed)linksError.value=cause.message}}
async function open(row){const token=++detailGeneration;dialog.value=true;actionDialog.value=false;selected.value=null;loading.value=true;error.value='';executionId.value='';staff.value=[];links.value=[];dutyRuns.value=[];try{const value=await responseRead('corrective-actions',typeof row==='string'?row:row.resourceId);if(token!==detailGeneration||disposed)return;if(props.deviceId&&!value.deviceIds.includes(props.deviceId))throw Error('固定整改不属于当前设备范围');selected.value=value;const results=await Promise.allSettled([responseRead('response-staff','','',{deviceIds:value.deviceIds.join(',')}),responseRead('response-evaluations',value.body.reviewRevisionId)]);if(token!==detailGeneration||disposed)return;if(results[0].status==='fulfilled')staff.value=results[0].value.items||[];else error.value=results[0].reason.message;if(results[1].status==='fulfilled'){const revision=await responseRead('response-revisions',results[1].value.parameters.executionRevisionId);if(token!==detailGeneration||disposed)return;executionId.value=revision.resourceId}else error.value=results[1].reason.message;await readLinks()}catch(cause){if(token===detailGeneration&&!disposed){error.value=cause.message;if([403,404].includes(cause.status))selected.value=null}}finally{if(token===detailGeneration)loading.value=false}}
function close(){detailGeneration++;dialog.value=false;actionDialog.value=false;selected.value=null}
async function begin(kind){const token=detailGeneration;action.value=kind;Object.assign(form,{owner:actionBody.value.owner||'',dueAt:actionBody.value.dueAt||null,explanation:'',evidence:[],followUpExecutionId:'',result:'',items:[],runId:'',ownerId:'',nextAction:'',idempotencyKey:createClientId()});actionDialog.value=true;saveError.value='';saving.value=false;if(kind==='DUTY_LINK'){try{const result=await dutyAll('runs',{status:'ACTIVE'});if(token===detailGeneration&&!disposed)dutyRuns.value=compatibleDutyRuns(result.items||[],selected.value.deviceIds)}catch(cause){if(token===detailGeneration&&!disposed)saveError.value=cause.message}}}
async function save(){if(saving.value||!selected.value)return;const token=detailGeneration;saving.value=true;saveError.value='';try{let body,operation;if(action.value==='VERIFY'){body=verificationPayload(form,selected.value,form.idempotencyKey);operation='verifications'}else if(action.value==='DUTY_LINK'){if(!form.runId||!selectedDutyRun.value?.memberIds?.includes(form.ownerId)||!form.nextAction.trim())throw Error('请选择范围内实际在岗班次、其成员与当班跟进内容');body={expectedVersion:selected.value.version,runId:form.runId,ownerId:form.ownerId,nextAction:form.nextAction.trim()};operation='duty-links'}else{if(!correctiveActions(actionBody.value).includes(action.value)||!form.explanation.trim())throw Error('当前状态不支持该操作，或缺少实际依据');const evidence=evidencePayload(form.evidence,selected.value.deviceIds);if(action.value==='SUBMIT_VERIFICATION'&&!evidence.length)throw Error('提交验收须关联处理证据');if(action.value==='ASSIGN'&&!form.owner)throw Error('请选择实际负责人');if(action.value==='LINK_FOLLOW_UP'&&!availableFollowUps.value.some(row=>row.resourceId===form.followUpExecutionId))throw Error('请选择覆盖本整改设备的实际后续执行');body={expectedVersion:selected.value.version,idempotencyKey:form.idempotencyKey,action:action.value,owner:form.owner,dueAt:form.dueAt||0,explanation:form.explanation.trim(),evidence,followUpExecutionId:form.followUpExecutionId};operation='actions'}const value=await responseWrite('corrective-actions',selected.value.resourceId,operation,body);if(token!==detailGeneration||disposed)return;if(action.value==='DUTY_LINK')await readLinks();else selected.value=value;actionDialog.value=false;UiMessage.success(action.value==='DUTY_LINK'?'已建立当班跟进，主业务验收状态独立保留':'整改记录已保存');emit('refresh')}catch(cause){if(token===detailGeneration&&!disposed)saveError.value=cause.status===409?'整改状态或版本已变化，请关闭操作并重新读取后再处理。':cause.message}finally{if(token===detailGeneration)saving.value=false}}
watch(()=>props.initialId,id=>{if(id)open(id)},{immediate:true});watch(()=>props.items,rows=>{const current=rows.find(row=>row.resourceId===selected.value?.resourceId);if(current)selected.value=current});watch(status,()=>page.value=1);watch(()=>form.runId,()=>form.ownerId='')
onBeforeUnmount(()=>{disposed=true;generation++;detailGeneration++})
</script>
<template><section class="response-stack"><div class="response-toolbar"><h3>整改与独立验收</h3><ui-select v-model="status" clearable placeholder="全部整改状态" style="width:200px"><ui-option v-for="value in ['OPEN','IN_PROGRESS','PENDING_VERIFICATION','DONE','CANCELLED']" :key="value" :value="value" :label="stateLabel(value)"/></ui-select></div><p class="response-hint">来源为已人工确认的固定复盘发现。提交处理、独立验收、当班跟进与后续演练分别保留状态。</p><div class="response-table-scroll"><ui-table :data="slice" empty-text="当前范围暂无整改事项。"><ui-table-column label="整改 / 设备" min-width="220"><template #default="{row}">{{row.body.title}}<p class="response-meta">{{row.deviceIds.map(deviceName).join('、')}}</p></template></ui-table-column><ui-table-column label="负责人 / 期限" min-width="220"><template #default="{row}">{{row.body.owner}}<p class="response-meta">{{responseTime(row.body.dueAt)}}</p></template></ui-table-column><ui-table-column label="状态 / 版本" min-width="160"><template #default="{row}"><span :data-response-corrective-state="row.resourceId">{{stateLabel(row.body.status)}}</span><p class="response-meta">版本 {{row.version}}</p></template></ui-table-column><ui-table-column label="操作" width="100"><template #default="{row}"><ui-button text size="small" :data-response-corrective="row.resourceId" @click="open(row)">处理与验收</ui-button></template></ui-table-column></ui-table></div><ui-pagination :current-page="page" :page-size="20" :total="rows.length" @current-change="page=$event"/></section>
<ui-dialog v-model="dialog" title="固定整改与独立验收" width="min(900px,94vw)" @close="close"><div class="response-dialog-body response-stack"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-skeleton v-if="loading" :rows="4"/><template v-if="selected"><article class="response-card response-stack"><h3>{{actionBody.title}}</h3><p>{{stateLabel(actionBody.status)}} · 版本 {{selected.version}}<br>负责人 {{personName(actionBody.owner)}} · 期限 {{responseTime(actionBody.dueAt)}}</p><p class="response-meta">来源复盘 {{actionBody.reviewRevisionId}}<br>固定事实 {{actionBody.reviewFactsHash}}</p><ui-button size="small" @click="emit('navigate','response',{executionId,runId:actionBody.reviewRevisionId,deviceId:selected.deviceIds[0]})">核对来源固定复盘</ui-button><div class="response-actions"><ui-button v-for="value in correctiveActions(actionBody)" v-show="can('POST /api/v1/corrective-actions/:id/actions')" :key="value" size="small" @click="begin(value)">{{actionLabels[value]}}</ui-button><ui-button v-if="actionBody.status==='PENDING_VERIFICATION'&&can('POST /api/v1/corrective-actions/:id/verifications')" type="primary" size="small" @click="begin('VERIFY')">独立验收</ui-button><ui-button v-if="!['DONE','CANCELLED'].includes(actionBody.status)&&can('POST /api/v1/corrective-actions/:id/duty-links')&&can('menu:duty')" size="small" @click="begin('DUTY_LINK')">建立当班跟进</ui-button></div></article><article class="response-card"><h4>规定验收项</h4><p v-for="item in actionBody.requiredVerification||[]" :key="item">{{item}}</p></article><article class="response-card"><h4>处理记录</h4><article v-for="row in actionBody.handling||[]" :key="row.id" class="response-card"><p>{{row.explanation}}</p><p class="response-meta">{{personName(row.actor)}} · {{responseTime(row.recordedAt)}} · 具体证据 {{row.evidence?.length||0}} 条</p><ResponseEvidenceList :items="row.evidence" :devices="selectedDevices" @navigate="(name,detail)=>emit('navigate',name,detail)"/></article><ui-empty v-if="!actionBody.handling?.length" description="尚未登记处理记录。"/></article><article class="response-card"><h4>独立验收历史</h4><article v-for="row in actionBody.verifications||[]" :key="row.id" class="response-card"><strong>{{stateLabel(row.result)}}</strong><p>{{row.explanation}}</p><p class="response-meta">{{row.items.join('、')}}<br>{{personName(row.actor)}} · {{responseTime(row.recordedAt)}} · 实际证据 {{row.evidence?.length||0}} 条</p><ResponseEvidenceList :items="row.evidence" :devices="selectedDevices" @navigate="(name,detail)=>emit('navigate',name,detail)"/></article><ui-empty v-if="!actionBody.verifications?.length" description="尚未进行独立验收。"/></article><article class="response-card response-stack"><h4>后续执行与当班跟进</h4><ui-button v-for="id in actionBody.followUpExecutionIds||[]" :key="id" text size="small" @click="emit('navigate','response',{executionId:id,deviceId:selected.deviceIds[0]})">读取后续演练或案例</ui-button><ui-alert v-if="linksError" :title="linksError" type="warning" :closable="false"/><article v-for="link in links" :key="link.dutyItemId"><p>关联时主业务版本 {{link.sourceVersion}} · {{responseTime(link.linkedAt)}}<br>{{link.linkedBy}}</p><ui-button text size="small" @click="emit('navigate','duty',{runId:link.runId,itemId:link.dutyItemId})">查看实际当班事项</ui-button></article><p class="response-hint">当前主业务状态 {{stateLabel(actionBody.status)}} · 负责人 {{personName(actionBody.owner)}}。当班事项完成不替代主业务验收。</p></article></template></div><template #footer><ui-button @click="close">关闭</ui-button></template></ui-dialog>
<ui-dialog v-model="actionDialog" :title="action==='VERIFY'?'独立验收':action==='DUTY_LINK'?'建立当班跟进':actionLabels[action]" width="min(800px,94vw)" :close-on-click-modal="false"><div class="response-dialog-body response-stack"><ui-alert v-if="saveError" :title="saveError" type="error" :closable="false"/><ui-form label-position="top" :disabled="saving"><template v-if="action==='DUTY_LINK'"><p class="response-hint">仅列出覆盖本整改设备的实际 ACTIVE 班次，负责人须为该班次成员。</p><ui-form-item label="实际当班班次" required><ui-select v-model="form.runId"><ui-option v-for="row in dutyRuns" :key="row.id" :value="row.id" :label="`${responseTime(row.startedAt)} · ${personName(row.leaderId)}`"/></ui-select></ui-form-item><ui-form-item label="实际当班负责人" required><ui-select v-model="form.ownerId"><ui-option v-for="id in selectedDutyRun?.memberIds||[]" :key="id" :value="id" :label="personName(id)"/></ui-select></ui-form-item><ui-form-item label="本班次具体跟进" required><ui-input v-model="form.nextAction" type="textarea" :rows="3" maxlength="2000"/></ui-form-item></template><template v-else><template v-if="action==='VERIFY'"><ui-form-item label="独立验收结论" required><ui-select v-model="form.result"><ui-option value="PASSED" label="验收通过"/><ui-option value="FAILED" label="验收失败，退回处理"/></ui-select></ui-form-item><ui-form-item label="本次已核实的规定项" required><div class="response-stack"><ui-checkbox v-for="item in actionBody.requiredVerification||[]" :key="item" :model-value="form.items.includes(item)" @update:model-value="value=>form.items=value?[...form.items,item]:form.items.filter(v=>v!==item)">{{item}}</ui-checkbox></div></ui-form-item></template><div v-if="action==='ASSIGN'" class="response-grid"><ui-form-item label="实际负责人" required><ui-select v-model="form.owner"><ui-option v-for="person in staff" :key="person.username" :value="person.username" :label="person.displayName||person.username"/></ui-select></ui-form-item><ui-form-item label="调整期限"><ui-date-time v-model="form.dueAt"/></ui-form-item></div><ui-form-item v-if="action==='LINK_FOLLOW_UP'" label="实际后续演练或案例" required><ui-select v-model="form.followUpExecutionId"><ui-option v-for="row in availableFollowUps" :key="row.resourceId" :value="row.resourceId" :label="`${row.body.name} · ${stateLabel(row.body.status)}`"/></ui-select></ui-form-item><ui-form-item label="实际处理或验收依据" required><ui-input v-model="form.explanation" type="textarea" :rows="3" maxlength="4000"/></ui-form-item><ResponseEvidenceEditor v-model="form.evidence" :devices="selectedDevices" :execution-id="executionId" :disabled="saving"/></template></ui-form></div><template #footer><ui-button :disabled="saving" @click="actionDialog=false">取消</ui-button><ui-button type="primary" :loading="saving" @click="save">保存实际记录</ui-button></template></ui-dialog>
</template>
